create table RB_AGREEMENT (AGREEMENT_ID VARCHAR(50) not null  ,SIGN_BRANCH VARCHAR(30) null  ,AGREEMENT_TYPE VARCHAR(10) null  ,AGREEMENT_CLASS VARCHAR(10) null  ,AGREEMENT_KEY_TYPE VARCHAR(2) null  ,AGREEMENT_KEY VARCHAR(30) null  ,AGREEMENT_AMT DECIMAL(17,2) null  ,AGRE_PROD_TYPE VARCHAR(20) null  ,SIGN_CHANNEL VARCHAR(10) null  ,TRAN_BRANCH VARCHAR(30) null  ,SIGN_DATE TIMESTAMP(3) null  ,SIGN_USER_ID VARCHAR(30) null  ,START_DATE TIMESTAMP(3) null  ,END_DATE TIMESTAMP(3) null  ,AGREEMENT_STATUS VARCHAR(3) null  ,AGREEMENT_CLOSE_ACCT_FLAG VARCHAR(1) null  ,BASE_ACCT_NO VARCHAR(50) null  ,PROD_TYPE VARCHAR(20) null  ,ACCT_CCY VARCHAR(3) null  ,ACCT_SEQ_NO VARCHAR(5) null  ,ACCT_NAME VARCHAR(100) null  ,CLIENT_NO VARCHAR(22) not null  ,CLIENT_SHORT VARCHAR(100) null  ,OPPOSITE_INTERNAL_KEY INT null  ,AGREEMENT_OPEN_DATE TIMESTAMP(3) null  ,OUT_SIGN_BRANCH VARCHAR(30) null  ,OUT_SIGN_CHANNEL VARCHAR(10) null  ,OUT_SIGN_DATE TIMESTAMP(3) null  ,OUT_SIGN_USER_ID VARCHAR(30) null  ,USER_ID VARCHAR(30) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  ,LAST_CHANGE_USER_ID VARCHAR(30) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,CREATE_TIMESTAMP VARCHAR(26) null  , primary key(AGREEMENT_ID,CLIENT_NO));